/* Sales CRM dashboard — FormLogic dashboard design language (kit values, plain CSS). */

@font-face {
  font-family: "Plus Jakarta Sans";
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

:root { --ax: var(--fl-accent); }
html.fl-dark { --ax: color-mix(in srgb, var(--fl-accent) 62%, #fff); }

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: "Plus Jakarta Sans", ui-sans-serif, system-ui, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color: var(--fl-text);
  background: radial-gradient(1000px 320px at 12% -100px, color-mix(in srgb, var(--fl-accent) 7%, transparent), transparent) var(--fl-bg);
}

.wrap { max-width: 1120px; margin: 0 auto; padding: 28px 24px 64px; }
.num { font-variant-numeric: tabular-nums lining-nums; }
:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 2px; border-radius: 4px; }
.load { padding: 90px 20px; text-align: center; color: var(--fl-muted); font-size: 13.5px; }

/* Header */
.hdr { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 22px; }
.hdr-l { display: flex; gap: 14px; min-width: 0; align-items: flex-start; flex: 1; }
.glyph {
  width: 40px; height: 40px; flex: none; display: grid; place-items: center; border-radius: 12px;
  color: var(--ax);
  background: color-mix(in srgb, var(--fl-accent) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--fl-accent) 22%, transparent);
}
.glyph svg { width: 22px; height: 22px; }
.title { margin: 1px 0 0; font-size: 24px; line-height: 1.12; font-weight: 750; letter-spacing: -0.02em; color: var(--fl-text); }
.brief { margin-top: 7px; font-size: 13px; line-height: 1.55; color: var(--fl-muted); }
.brief b { color: var(--fl-text); font-weight: 650; font-variant-numeric: tabular-nums; }
.brief .dot { margin: 0 7px; color: var(--fl-faint); }
.hdr-r { display: flex; gap: 10px; flex: none; align-items: center; padding-top: 2px; }

/* Buttons */
.btn {
  appearance: none; cursor: pointer; border-radius: 11px; padding: 10px 16px;
  font-weight: 650; font-size: 13.5px; font-family: inherit;
  display: inline-flex; align-items: center; gap: 8px; white-space: nowrap;
  transition: filter .15s ease, transform .06s ease, border-color .15s ease;
}
.btn:active { transform: translateY(1px); }
.btn svg { width: 16px; height: 16px; }
.btn-primary {
  border: 0; background: var(--fl-accent); color: var(--fl-accent-contrast);
  box-shadow: 0 8px 20px -10px color-mix(in srgb, var(--fl-accent) 70%, transparent);
}
.btn-primary:hover { filter: brightness(1.07); }
.btn-ghost { background: transparent; border: 1px solid var(--fl-border); color: var(--fl-text); }
.btn-ghost:hover { border-color: color-mix(in srgb, var(--fl-accent) 45%, transparent); }

/* KPI lede */
.kpis { display: grid; grid-template-columns: 1.6fr 1fr 1fr 1fr; gap: 14px; }
.kpi {
  background: var(--fl-surface); border: 1px solid var(--fl-border); border-radius: 16px;
  padding: 16px 18px; box-shadow: var(--fl-shadow); min-width: 0;
  display: flex; flex-direction: column;
}
.kpi:not(.kpi-hero) { justify-content: center; }
.kpi-label { font-size: 11px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--fl-muted); }
.kpi-val { margin-top: 7px; font-size: 25px; font-weight: 800; letter-spacing: -0.02em; line-height: 1.05; color: var(--fl-text); font-variant-numeric: tabular-nums; }
.kpi-hero .kpi-val { font-size: 33px; }
.kpi-sub { margin-top: 5px; font-size: 12px; color: var(--fl-faint); }
.kpi-sub b { color: var(--fl-muted); font-weight: 650; font-variant-numeric: tabular-nums; }
.kpi-spark { margin-top: auto; padding-top: 10px; }
.kpi-spark svg { display: block; width: 100%; height: 42px; }

/* Section label */
.sec {
  display: flex; align-items: center; gap: 10px; margin: 24px 0 12px;
  font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--fl-muted);
}
.sec::after { content: ""; flex: 1; height: 1px; background: var(--fl-border); }

/* Grid + panels */
.grid { display: grid; gap: 14px; align-items: start; }
.g21 { grid-template-columns: 2fr 1fr; }
.g11 { grid-template-columns: 1fr 1fr; }
.panel {
  background: var(--fl-surface); border: 1px solid var(--fl-border); border-radius: 16px;
  box-shadow: var(--fl-shadow); padding: 16px 18px; min-width: 0;
}
.panel-h { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.panel-t { font-size: 13.5px; font-weight: 700; color: var(--fl-text); }
.panel-link { background: none; border: 0; padding: 0; cursor: pointer; font-family: inherit; font-size: 12px; font-weight: 650; color: var(--ax); }
.panel-link:hover { text-decoration: underline; }

/* Rows */
.rows { display: flex; flex-direction: column; }
.row { display: flex; align-items: center; gap: 12px; padding: 10px 0; border-top: 1px solid var(--fl-border); }
.row:first-child { border-top: 0; padding-top: 2px; }
.rows .row:last-child { padding-bottom: 2px; }
.row-main { min-width: 0; flex: 1; }
.row-title { font-size: 13.5px; font-weight: 600; color: var(--fl-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row-sub { margin-top: 2px; font-size: 12px; color: var(--fl-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row-r { text-align: right; flex: none; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.amt { font-size: 13.5px; font-weight: 700; color: var(--fl-text); font-variant-numeric: tabular-nums; }
.pill { display: inline-flex; align-items: center; font-size: 10.5px; font-weight: 700; padding: 3px 9px; border-radius: 999px; white-space: nowrap; }
.chip { font-size: 11.5px; font-weight: 650; color: var(--fl-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }

/* Breakdown bars */
.bar-row { display: grid; grid-template-columns: minmax(90px, 150px) 1fr 64px; align-items: center; gap: 10px; padding: 5px 0; }
.bar-name { font-size: 12.5px; color: var(--fl-muted); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.bar-track { height: 8px; border-radius: 5px; background: var(--fl-track); overflow: hidden; }
.bar-fill { display: block; height: 100%; width: 0; border-radius: 5px; background: var(--fl-accent); transition: width .9s cubic-bezier(.22, 1, .36, 1); }
.bar-val { font-size: 12.5px; font-weight: 700; color: var(--fl-text); text-align: right; font-variant-numeric: tabular-nums; }
.bar-val small { display: block; font-size: 10.5px; font-weight: 600; color: var(--fl-faint); }

/* Quick actions */
.acts { display: flex; flex-wrap: wrap; gap: 10px; }
.act {
  display: inline-flex; align-items: center; gap: 9px;
  background: var(--fl-surface); border: 1px solid var(--fl-border); color: var(--fl-text);
  border-radius: 12px; padding: 10px 14px; cursor: pointer;
  font-family: inherit; font-weight: 600; font-size: 13px;
  transition: border-color .15s ease, transform .06s ease, box-shadow .15s ease;
}
.act:hover { border-color: color-mix(in srgb, var(--fl-accent) 50%, transparent); box-shadow: var(--fl-shadow); }
.act:active { transform: translateY(1px); }
.act svg { width: 16px; height: 16px; color: var(--ax); }

/* Empty states */
.empty { padding: 22px 12px; text-align: center; color: var(--fl-muted); font-size: 13px; line-height: 1.5; }
.empty svg { width: 22px; height: 22px; color: var(--fl-faint); display: block; margin: 0 auto 8px; }
.link-btn { background: none; border: 0; padding: 4px 0; color: var(--ax); cursor: pointer; font-family: inherit; font-weight: 650; font-size: 13px; }
.link-btn:hover { text-decoration: underline; }

/* Motion */
.reveal { opacity: 0; transform: translateY(10px); animation: flin .55s cubic-bezier(.22, 1, .36, 1) forwards; }
@keyframes flin { to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  .reveal { animation: none; opacity: 1; transform: none; }
  .bar-fill { transition: none; }
}

@media (max-width: 960px) {
  .kpis { grid-template-columns: 1fr 1fr; }
  .g21, .g11 { grid-template-columns: 1fr; }
}
@media (max-width: 600px) {
  .wrap { padding: 20px 14px 48px; }
  .kpi-hero { grid-column: 1 / -1; }
  .kpis .kpi:last-child:nth-child(even) { grid-column: 1 / -1; }
  .hdr-r { width: 100%; flex-wrap: wrap; }
  .hdr-r .btn { flex: 1; justify-content: center; }
  .bar-row { grid-template-columns: minmax(76px, 110px) 1fr 52px; }
  .title { font-size: 21px; }
}

// data.ts — types, pipeline constants, and pure helpers for the CRM dashboard.
// Imported by index.ts with a relative path (proves multi-file bundling).

export interface FieldMeta {
  id: string;
  label: string;
  type: string;
}

export interface FormMeta {
  formId: string;
  displayName: string;
  fields: FieldMeta[];
}

export interface AppContext {
  appName: string;
  appSlug: string;
  forms: FormMeta[];
}

export interface CrmRecord {
  id: string;
  answers: Record<string, unknown>;
  submittedAt: string;
}

// Pill kinds map onto the kit's status tints (--fl-good/warn/bad/accent/neutral).
export type PillKind = "neutral" | "accent" | "warn" | "good" | "bad";

export interface StageInfo {
  value: string;
  label: string;
  color: string; // bar fill — always a --fl-* based color, never a hex
  pill: PillKind;
  open: boolean;
}

// Pipeline stages in display order. `value` matches the Deal.stage dropdown value.
// Colors ramp up the accent through the open stages, then resolve to good/bad.
export const STAGES: StageInfo[] = [
  { value: "lead", label: "Lead", color: "color-mix(in srgb, var(--fl-accent) 55%, transparent)", pill: "neutral", open: true },
  { value: "qualified", label: "Qualified", color: "color-mix(in srgb, var(--fl-accent) 78%, transparent)", pill: "accent", open: true },
  { value: "proposal", label: "Proposal", color: "var(--fl-accent)", pill: "warn", open: true },
  { value: "won", label: "Won", color: "var(--fl-good)", pill: "good", open: false },
  { value: "lost", label: "Lost", color: "var(--fl-bad)", pill: "bad", open: false },
];

export function stageInfo(value: string): StageInfo {
  const found = STAGES.find((s) => s.value === value);
  return (
    found ?? {
      value,
      label: value || "Unknown",
      color: "color-mix(in srgb, var(--fl-muted) 55%, transparent)",
      pill: "neutral",
      open: true,
    }
  );
}

// Resolve a form by fuzzy displayName match (e.g. base "contact" matches "Contacts").
export function findForm(ctx: AppContext, base: string): FormMeta | undefined {
  const needle = base.trim().toLowerCase();
  return ctx.forms.find((f) => (f.displayName || "").trim().toLowerCase().includes(needle));
}

export function toNumber(value: unknown): number {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  if (typeof value === "string") {
    const n = parseFloat(value.replace(/[^0-9.\-]/g, ""));
    return Number.isFinite(n) ? n : 0;
  }
  return 0;
}

export function toText(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return "";
}

// linked_record answers can arrive as an id string, an array, or an object.
export function linkedId(value: unknown): string {
  if (!value) return "";
  if (typeof value === "string") return value;
  if (Array.isArray(value)) return linkedId(value[0]);
  if (typeof value === "object") {
    const obj = value as Record<string, unknown>;
    return toText(obj.id ?? obj.value ?? obj.recordId ?? "");
  }
  return "";
}

export function formatCurrency(amount: number): string {
  return "$" + Math.round(amount).toLocaleString("en-US");
}

export function formatCompact(amount: number): string {
  const abs = Math.abs(amount);
  if (abs >= 1_000_000) return "$" + (amount / 1_000_000).toFixed(1).replace(/\.0$/, "") + "M";
  if (abs >= 1_000) return "$" + (amount / 1_000).toFixed(1).replace(/\.0$/, "") + "k";
  return "$" + Math.round(amount);
}

export interface StageBucket {
  stage: StageInfo;
  total: number;
  count: number;
}

export function pipelineByStage(deals: CrmRecord[]): StageBucket[] {
  return STAGES.map((stage) => {
    const matching = deals.filter((d) => toText(d.answers["stage"]) === stage.value);
    const total = matching.reduce((sum, d) => sum + toNumber(d.answers["amount"]), 0);
    return { stage, total, count: matching.length };
  });
}

// Weekly record counts (oldest week first) for the hero KPI sparkline.
export function weeklyCounts(records: CrmRecord[], weeks = 8): number[] {
  const out: number[] = new Array(weeks).fill(0);
  const now = Date.now();
  for (const r of records) {
    const d = new Date(r.submittedAt || "");
    if (Number.isNaN(d.getTime())) continue;
    const wk = Math.floor((now - d.getTime()) / 604800000);
    if (wk >= 0 && wk < weeks) out[weeks - 1 - wk]++;
  }
  return out;
}

export function formatShortDate(value: string): string {
  const d = new Date(value || "");
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

// Build a lookup of Contact record id -> display name for linked-record rendering.
export function contactNameMap(contacts: CrmRecord[]): Record<string, string> {
  const map: Record<string, string> = {};
  for (const c of contacts) {
    const name = toText(c.answers["name"]) || toText(c.answers["company"]) || toText(c.answers["email"]);
    if (c.id) map[c.id] = name || "Unnamed contact";
  }
  return map;
}

// index.ts — entry point. Wires the DOM to the app-scoped FormLogic SDK and
// renders a live sales-pipeline dashboard in the FormLogic dashboard design
// language (glyph header + briefing, KPI lede, section labels, kit rows/pills).
// Bundled by esbuild (relative imports only).
import {
  AppContext,
  CrmRecord,
  FormMeta,
  PillKind,
  contactNameMap,
  findForm,
  formatCompact,
  formatCurrency,
  formatShortDate,
  linkedId,
  pipelineByStage,
  stageInfo,
  toNumber,
  toText,
  weeklyCounts,
} from "./data";

interface FormLogicSdk {
  context(): Promise<AppContext>;
  submit(formId: string, answers: Record<string, unknown>): Promise<unknown>;
  records(formId: string, opts?: { limit?: number }): Promise<CrmRecord[]>;
  currentUser(): Promise<{ name?: string; email?: string } | null>;
  navigate(target: string): void;
  toast: { success(msg: string): void; error(msg: string): void };
  escapeHtml(value: unknown): string;
}

declare global {
  interface Window {
    FormLogic: FormLogicSdk;
  }
}

const FL = window.FormLogic;
const esc = (v: unknown): string => FL.escapeHtml(v);
const root = document.getElementById("app");

let reducedMotion = false;
try {
  reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
} catch {
  /* older engines */
}

// ── Inline SVG icons (24 viewBox, stroke 1.75, currentColor — no emoji) ──
const icoSvg = (d: string): string =>
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
  d +
  "</svg>";

const I = {
  target: icoSvg('<circle cx="12" cy="12" r="8.5"/><circle cx="12" cy="12" r="4.75"/><circle cx="12" cy="12" r="1.1"/>'),
  plus: icoSvg('<path d="M12 5v14M5 12h14"/>'),
  user: icoSvg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 20.5c.7-3.4 3.7-5 7.5-5s6.8 1.6 7.5 5"/>'),
  money: icoSvg('<path d="M12 2.5v19"/><path d="M16.5 6H9.75a3.25 3.25 0 0 0 0 6.5h4.5a3.25 3.25 0 0 1 0 6.5H7"/>'),
  clock: icoSvg('<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>'),
  refresh: icoSvg('<path d="M20 12a8 8 0 1 1-2.34-5.66"/><path d="M20 3.5V8h-4.5"/>'),
  chart: icoSvg('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>'),
};

void main();

async function main(): Promise<void> {
  if (!root) return;
  if (!FL) {
    root.innerHTML = '<div class="wrap"><div class="load">FormLogic SDK unavailable.</div></div>';
    return;
  }
  try {
    const ctx = await FL.context();
    const user = await FL.currentUser().catch(() => null);

    const contactForm = findForm(ctx, "contact");
    const dealForm = findForm(ctx, "deal");
    const activityForm = findForm(ctx, "activit");

    const [deals, contacts] = await Promise.all([
      dealForm ? FL.records(dealForm.formId, { limit: 500 }) : Promise.resolve([]),
      contactForm ? FL.records(contactForm.formId, { limit: 500 }) : Promise.resolve([]),
    ]);

    render(ctx, user, { contactForm, dealForm, activityForm }, deals, contacts);
  } catch (err) {
    root.innerHTML =
      '<div class="wrap"><div class="load">Could not load the dashboard. ' +
      esc(err instanceof Error ? err.message : String(err)) +
      "</div></div>";
  }
}

interface Forms {
  contactForm?: FormMeta;
  dealForm?: FormMeta;
  activityForm?: FormMeta;
}

function render(
  ctx: AppContext,
  user: { name?: string; email?: string } | null,
  forms: Forms,
  deals: CrmRecord[],
  contacts: CrmRecord[]
): void {
  if (!root) return;
  void user; // greeting was replaced by the briefing line

  const buckets = pipelineByStage(deals);
  const openPipeline = buckets.filter((b) => b.stage.open).reduce((s, b) => s + b.total, 0);
  const wonBucket = buckets.find((b) => b.stage.value === "won");
  const wonTotal = wonBucket ? wonBucket.total : 0;
  const wonCount = wonBucket ? wonBucket.count : 0;
  const openCount = deals.filter((d) => stageInfo(toText(d.answers["stage"])).open).length;
  const maxBar = Math.max(1, ...buckets.map((b) => b.total));
  const names = contactNameMap(contacts);

  const briefing = brief([
    `<b>${openCount}</b> active deal${openCount === 1 ? "" : "s"}`,
    `<b>${esc(formatCompact(openPipeline))}</b> open pipeline`,
    `<b>${esc(formatCompact(wonTotal))}</b> won`,
    `<b>${contacts.length}</b> contact${contacts.length === 1 ? "" : "s"}`,
  ]);

  const dealsNav = forms.dealForm ? "form/" + forms.dealForm.formId + "/responses" : "";
  const contactsNav = forms.contactForm ? "form/" + forms.contactForm.formId + "/responses" : "";

  const heroSub =
    openCount > 0
      ? `<b>${openCount}</b> active deal${openCount === 1 ? "" : "s"} &middot; avg ${esc(formatCompact(openPipeline / openCount))}`
      : "No open deals yet &middot; add your first deal";
  const heroSpark = spark(weeklyCounts(deals, 8));

  root.innerHTML = `
    <div class="wrap">
      <header class="hdr">
        <div class="hdr-l">
          <div class="glyph">${I.target}</div>
          <div style="min-width:0">
            <h1 class="title">${esc(ctx.appName || "Sales CRM")}</h1>
            <div class="brief">${briefing}</div>
          </div>
        </div>
        <div class="hdr-r">
          <button class="btn btn-ghost" id="refresh" type="button">${I.refresh}<span>Refresh</span></button>
          <button class="btn btn-primary" id="new-deal" type="button">${I.plus}<span>New deal</span></button>
        </div>
      </header>

      <section class="kpis">
        <div class="kpi kpi-hero">
          <div class="kpi-label">Open pipeline</div>
          <div class="kpi-val">${esc(formatCurrency(openPipeline))}</div>
          <div class="kpi-sub">${heroSub}</div>
          ${heroSpark ? `<div class="kpi-spark">${heroSpark}</div>` : ""}
        </div>
        <div class="kpi">
          <div class="kpi-label">Won</div>
          <div class="kpi-val">${esc(formatCurrency(wonTotal))}</div>
          <div class="kpi-sub">${pill(`${wonCount} closed`, "good")}</div>
        </div>
        <div class="kpi">
          <div class="kpi-label">Contacts</div>
          <div class="kpi-val"><span data-count="${contacts.length}">${contacts.length.toLocaleString()}</span></div>
          <div class="kpi-sub">in your book</div>
        </div>
        <div class="kpi">
          <div class="kpi-label">Total deals</div>
          <div class="kpi-val"><span data-count="${deals.length}">${deals.length.toLocaleString()}</span></div>
          <div class="kpi-sub">all stages</div>
        </div>
      </section>

      ${sec("Pipeline")}
      <section class="grid g21">
        ${panel(
          "Value by stage",
          deals.length
            ? renderBars(buckets, maxBar)
            : emptyBlock(I.chart, "Deal values will chart here by stage.", forms.dealForm, "+ Add a deal"),
          dealsNav
        )}
        ${panel(
          "Recent contacts",
          contacts.length
            ? renderRecentContacts(contacts)
            : emptyBlock(I.user, "The people you add will appear here.", forms.contactForm, "+ Add a contact"),
          contactsNav
        )}
      </section>

      ${sec("Recent deals")}
      ${panel(
        "Latest opportunities",
        deals.length
          ? renderRecentDeals(deals, names)
          : emptyBlock(I.money, "Deals you create will appear here.", forms.dealForm, "+ Add a deal"),
        dealsNav
      )}

      ${sec("Quick add")}
      <section class="acts">
        ${act("act-contact", I.user, "New contact", forms.contactForm)}
        ${act("act-deal", I.money, "New deal", forms.dealForm)}
        ${act("act-activity", I.clock, "Log activity", forms.activityForm)}
      </section>
    </div>
  `;

  wire(forms);
}

// ── Kit-grammar building blocks ──

function brief(clauses: string[]): string {
  return clauses.filter(Boolean).join('<span class="dot">&middot;</span>');
}

function sec(label: string): string {
  return `<div class="sec">${esc(label)}</div>`;
}

function panel(title: string, body: string, nav?: string, navLabel?: string): string {
  const link = nav
    ? `<button class="panel-link" type="button" data-nav="${esc(nav)}">${esc(navLabel || "View all")}</button>`
    : "";
  return `<div class="panel"><div class="panel-h"><div class="panel-t">${esc(title)}</div>${link}</div>${body}</div>`;
}

function pill(text: string, kind: PillKind): string {
  const c =
    kind === "good" ? "var(--fl-good)" :
    kind === "warn" ? "var(--fl-warn)" :
    kind === "bad" ? "var(--fl-bad)" :
    kind === "accent" ? "var(--ax)" : "var(--fl-muted)";
  const bg = kind === "neutral" ? "var(--fl-track)" : `color-mix(in srgb, ${c} 15%, transparent)`;
  return `<span class="pill" style="color:${c};background:${bg}">${esc(text)}</span>`;
}

function emptyBlock(icon: string, msg: string, form?: FormMeta, cta?: string): string {
  const link = form
    ? `<div><button class="link-btn" type="button" data-nav="${esc(form.formId)}">${esc(cta || "+ Add one")}</button></div>`
    : "";
  return `<div class="empty">${icon}${esc(msg)}${link}</div>`;
}

function act(id: string, icon: string, label: string, form?: FormMeta): string {
  const disabled = form ? "" : ' aria-disabled="true" style="opacity:.5;cursor:not-allowed"';
  return `<button class="act" type="button" id="${esc(id)}"${disabled}>${icon}<span>${esc(label)}</span></button>`;
}

function spark(vals: number[], w = 220, hh = 42): string {
  if (!vals || vals.length < 2) return "";
  let mx = 0;
  let mn = Infinity;
  for (const v of vals) {
    if (v > mx) mx = v;
    if (v < mn) mn = v;
  }
  if (mx === 0) return "";
  if (mn === mx) mn = 0;
  const rng = mx - mn || 1;
  const pts: string[] = [];
  for (let j = 0; j < vals.length; j++) {
    const x = 2 + (j / (vals.length - 1)) * (w - 4);
    const y = hh - 5 - ((vals[j] - mn) / rng) * (hh - 12);
    pts.push(x.toFixed(1) + "," + y.toFixed(1));
  }
  const line = pts.join(" ");
  return (
    `<svg viewBox="0 0 ${w} ${hh}" preserveAspectRatio="none" aria-hidden="true">` +
    `<polygon points="2,${hh - 2} ${line} ${w - 2},${hh - 2}" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/>` +
    `<polyline points="${line}" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>` +
    "</svg>"
  );
}

// ── Panel bodies ──

function renderBars(buckets: ReturnType<typeof pipelineByStage>, maxBar: number): string {
  return buckets
    .map((b) => {
      const pct = b.total > 0 ? Math.max(4, Math.round((b.total / maxBar) * 100)) : 0;
      return `
        <div class="bar-row">
          <span class="bar-name" title="${esc(b.stage.label)}">${esc(b.stage.label)}</span>
          <div class="bar-track"><div class="bar-fill" data-pct="${pct}" style="background:${b.stage.color}"></div></div>
          <span class="bar-val">${esc(formatCompact(b.total))}<small>${b.count} deal${b.count === 1 ? "" : "s"}</small></span>
        </div>`;
    })
    .join("");
}

function renderRecentDeals(deals: CrmRecord[], names: Record<string, string>): string {
  const recent = [...deals].sort(bySubmittedDesc).slice(0, 6);
  const items = recent
    .map((d) => {
      const title = toText(d.answers["title"]) || "Untitled deal";
      const st = stageInfo(toText(d.answers["stage"]));
      const amount = formatCurrency(toNumber(d.answers["amount"]));
      const cid = linkedId(d.answers["contact"]);
      const contactName = cid && names[cid] ? names[cid] : cid ? "Linked contact" : "No contact";
      return `
        <div class="row">
          <div class="row-main">
            <div class="row-title">${esc(title)}</div>
            <div class="row-sub">${esc(contactName)}</div>
          </div>
          <div class="row-r">
            <span class="amt">${esc(amount)}</span>
            ${pill(st.label, st.pill)}
          </div>
        </div>`;
    })
    .join("");
  return `<div class="rows">${items}</div>`;
}

function renderRecentContacts(contacts: CrmRecord[]): string {
  const recent = [...contacts].sort(bySubmittedDesc).slice(0, 6);
  const items = recent
    .map((c) => {
      const name = toText(c.answers["name"]) || "Unnamed";
      const company = toText(c.answers["company"]);
      const email = toText(c.answers["email"]);
      const sub = [company, email].filter(Boolean).join(" · ") || "—";
      const added = formatShortDate(c.submittedAt);
      return `
        <div class="row">
          <div class="row-main">
            <div class="row-title">${esc(name)}</div>
            <div class="row-sub">${esc(sub)}</div>
          </div>
          ${added ? `<div class="row-r"><span class="chip">${esc(added)}</span></div>` : ""}
        </div>`;
    })
    .join("");
  return `<div class="rows">${items}</div>`;
}

function bySubmittedDesc(a: CrmRecord, b: CrmRecord): number {
  return String(b.submittedAt || "").localeCompare(String(a.submittedAt || ""));
}

// ── Wiring: navigation, staggered reveal, bar draw, count-up ──

function wire(forms: Forms): void {
  if (!root) return;

  const go = (form?: FormMeta): void => {
    if (form) {
      FL.navigate(form.formId);
    } else {
      FL.toast.error("That form isn't available in this app.");
    }
  };

  document.getElementById("refresh")?.addEventListener("click", () => {
    FL.toast.success("Refreshing…");
    void main();
  });
  document.getElementById("new-deal")?.addEventListener("click", () => go(forms.dealForm));
  document.getElementById("act-contact")?.addEventListener("click", () => go(forms.contactForm));
  document.getElementById("act-deal")?.addEventListener("click", () => go(forms.dealForm));
  document.getElementById("act-activity")?.addEventListener("click", () => go(forms.activityForm));

  // Generic navigation: panel "View all" links + empty-state CTAs.
  root.querySelectorAll<HTMLElement>("[data-nav]").forEach((el) => {
    el.addEventListener("click", () => {
      const target = el.getAttribute("data-nav");
      if (target) FL.navigate(target);
    });
  });

  // Staggered fade-up reveal (CSS kills it under prefers-reduced-motion).
  root.querySelectorAll<HTMLElement>(".wrap > *").forEach((el, i) => {
    el.classList.add("reveal");
    el.style.animationDelay = `${Math.min(i, 8) * 60}ms`;
  });

  // Draw the stage bars after first paint so the width transition runs.
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      root.querySelectorAll<HTMLElement>(".bar-fill").forEach((f) => {
        f.style.width = (f.getAttribute("data-pct") || "0") + "%";
      });
    });
  });

  if (!reducedMotion) {
    root.querySelectorAll<HTMLElement>("[data-count]").forEach(countUp);
  }
}

function countUp(el: HTMLElement): void {
  const target = parseFloat(el.getAttribute("data-count") || "");
  if (!Number.isFinite(target) || target <= 0) return;
  let t0: number | null = null;
  const dur = 700;
  const step = (ts: number): void => {
    if (t0 === null) t0 = ts;
    const p = Math.min(1, (ts - t0) / dur);
    const eased = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(target * eased).toLocaleString();
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}
